            pepLenRankCounts.put(peptideLength, rankCounts);
            List<Double> pepLengthRanks = pepLenRanks.get(peptideLength);
            if(pepLengthRanks == null)
                continue;
            totalPositivesCount += pepLengthRanks.size();
            for(double rank : pepLengthRanks)
            {
