import java.util.Arrays;
import java.util.List;
import zmq.TcpAddress.TcpAddressMask;
public class Options
{
    //  High-water marks for message pipes.
    int sendHwm;
    int recvHwm;
    //  I/O thread affinity.
    long affinity;
    //  Socket identity
    byte identitySize;
    byte[] identity; // [256];
    // Last socket endpoint resolved URI
    String lastEndpoint;
    //  Maximum tranfer rate [kb/s]. Default 100kb/s.
    int rate;
    //  Reliability time interval [ms]. Default 10 seconds.
    int recoveryIvl;
    // Sets the time-to-live field in every multicast packet sent.
    int multicastHops;
    // SO_SNDBUF and SO_RCVBUF to be passed to underlying transport sockets.
    int sndbuf;
    int rcvbuf;
    //  Socket type.
    int type;
    //  Linger time, in milliseconds.
    int linger;
    //  Minimum interval between attempts to reconnect, in milliseconds.
    //  Default 100ms
    int reconnectIvl;
    //  Maximum interval between attempts to reconnect, in milliseconds.
    //  Default 0 (unused)
    int reconnectIvlMax;
    //  Maximum backlog for pending connections.
    int backlog;
    //  Maximal size of message to handle.
    long maxMsgSize;
    // The timeout for send/recv operations for this socket.
    int recvTimeout;
    int sendTimeout;
    //  If 1, indicates the use of IPv4 sockets only, it will not be
    //  possible to communicate with IPv6-only hosts. If 0, the socket can
    //  connect to and accept connections from both IPv4 and IPv6 hosts.
    int ipv4only;
    //  If 1, connecting pipes are not attached immediately, meaning a send()
    //  on a socket with only connecting pipes would block
    int delayAttachOnConnect;
    //  If true, session reads all the pending messages from the pipe and
    //  sends them to the network when socket is closed.
    boolean delayOnClose;
    //  If true, socket reads all the messages from the pipe and delivers
    //  them to the user when the peer terminates.
    boolean delayOnDisconnect;
    //  If 1, (X)SUB socket should filter the messages. If 0, it should not.
    boolean filter;
    //  If true, the identity message is forwarded to the socket.
    boolean recvIdentity;
    //  TCP keep-alive settings.
    //  Defaults to -1 = do not change socket options
    int tcpKeepAlive;
    int tcpKeepAliveCnt;
    int tcpKeepAliveIdle;
    int tcpKeepAliveIntvl;
    // TCP accept() filters
    //typedef std::vector <tcp_address_mask_t> tcp_accept_filters_t;
    final List<TcpAddress.TcpAddressMask> tcpAcceptFilters;
    //  ID of the socket.
    int socketId;
    Class<? extends DecoderBase> decoder;
    Class<? extends EncoderBase> encoder;
    MsgAllocator msgAllocator;
    public Options()
    {
        sendHwm = 1000;
        recvHwm = 1000;
        affinity = 0;
        identitySize = 0;
        rate = 100;
        recoveryIvl = 10000;
        multicastHops = 1;
        sndbuf = 0;
        rcvbuf = 0;
        type = -1;
        linger = -1;
        reconnectIvl = 100;
        reconnectIvlMax = 0;
        backlog = 100;
        maxMsgSize = -1;
        recvTimeout = -1;
        sendTimeout = -1;
        ipv4only = 1;
        delayAttachOnConnect =  0;
        delayOnClose = true;
        delayOnDisconnect = true;
        filter = false;
        recvIdentity = false;
        tcpKeepAlive = -1;
        tcpKeepAliveCnt = -1;
        tcpKeepAliveIdle = -1;
        tcpKeepAliveIntvl = -1;
        socketId = 0;
        identity = null;
        tcpAcceptFilters = new ArrayList<TcpAddress.TcpAddressMask>();
        decoder = null;
        encoder = null;
        msgAllocator = null;
