                    e.printStackTrace();
                }
            }
            if(role == null) {
                role = getOrCreateTopic(topicmap, getSIPrefix()+"role-1", "role 1");
            }
            return role;
        }

        @Override
        public Topic getRole2Topic(TopicMap topicmap, Map<String,String> optionsValues) {
            String roleStr = null;
