        this.fileName = fileName;
    }

    public String getDownloadFolder() {
        return folder;
    }

    public String getFileName() {
        return fileName;
    }

    public String getUrl() {
        return url.toString();
    }

    public int getDownloaded() {
        return downloaded;
    }

    public int getSize() {
        return size;
    }

    public float getProgress() {
        return ((float) downloaded / size) * 100;
    }

    public int getStatus() {
        return status;
    }

    public void pause() {
        status = PAUSED;
        reportState();
    }

    public void resume() {
        status = DOWNLOADING;
        reportState();
        download();
    }

    public void cancel() {
        status = CANCELLED;
        reportState();

        File file = new File(folder + "\\" + fileName + ".osz");
        file.delete();

        downloaded = 0;
    }

    private void error() {
    	System.out.println("Errored!!");
        status = ERROR;
        reportState();
    }

    public void download() {
        if (status != DOWNLOADING && status != COMPLETED) {
            status = DOWNLOADING;
            Thread thread = new Thread(this);
            thread.start();
            reportState();
        }
    }

    @Override
    public void run() {
        RandomAccessFile file = null;
        InputStream in = null;

        try {
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestProperty("Range", "bytes=" + downloaded + "-");

            osu.setCookies(conn);

            conn.connect();
            
            int code = conn.getResponseCode() / 100;
            if (code < 2 && code > 3) {
                error();
            }

            int len = conn.getContentLength();

            if (len < 1) {
                error();
            }

            if (size == -1) {
                size = len;
                reportState();
            }

            file = new RandomAccessFile(folder + "\\" + fileName + ".osz", "rw");
            file.seek(downloaded);

            in = conn.getInputStream();

            while (status == DOWNLOADING) {
                byte[] buffer = size - downloaded > MAX_BUFFER_SIZE ? new byte[MAX_BUFFER_SIZE]
                        : new byte[size - downloaded];
                int read = in.read(buffer);
                if (read == -1) {
                    break;
                }

                file.write(buffer, 0, read);
                downloaded += read;
                reportState();
            }

            if (status == DOWNLOADING) {
                status = COMPLETED;
                reportState();
            }
        } catch (IOException e) {
        	e.printStackTrace();
            DumpManager.addDump(dump = new DebugDump(null, "(Try&catch try)", "Error reporting and debug dump",
                    "(Try&catch finally)", "Error when downloading", false, e));
            error();
        } finally {
            if (file != null) {
                try {
                    file.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }

            if (in != null) {
                try {
                    in.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private void reportState() {
        setChanged();
        notifyObservers();
    }

    private static String join(String separator, List<HttpCookie> objs) {
        String out = "";

        String str;
        for (int i = 0; i < objs.size(); i++) {
            str = objs.get(i).toString();

            out += str + separator;

            if (i != objs.size() - 1) {
                out += " ";
            }
        }

        return out;
    }

	@Override
	public DebugDump getErrorDump() {
		return dump;
	}

}
