            key = it.next();
            
            if (last != null && compareVersion(key, last) != 1){
                continue;
            } else {
                last = key;
            }
        }
        
        if (last == null){
            return null;
        }
        
        buildsArr = versionsJson.getJSONArray(last);
        
        int latest = buildsArr.length();
        
        JSONObject verJson = buildsArr.getJSONObject(latest - 1);
        
