    band_samples = sample_array[self.bandIndex]
    n_samples = len(band_samples)

    self.ensureExtraCapacity(n_samples)
    start = self.n_bits
    end = start + n_samples
    self.bits[start:end] = BandBitEncoder.convertBand(band_samples)
