app/src/main/java/com/huawei/android/hms/agent/common/ApiClientMgr.java
public final class ApiClientMgr implements HuaweiApiClient.ConnectionCallbacks, HuaweiApiClient.OnConnectionFailedListener, IActivityResumeCallback {

    /**
     * 单实例
     */
    public static final ApiClientMgr INST = new ApiClientMgr();

    /**
     * 应用市场包名
     */
    private static final String PACKAGE_NAME_HIAPP = "com.huawei.appmarket";

    /**
     * 回调锁，避免连接回调紊乱
     */
    private static final Object CALLBACK_LOCK = new Object();

    /**
     * 静态注册回调锁，避免注册和回调紊乱
     */
    private static final Object STATIC_CALLBACK_LOCK = new Object();

    /**
     * client操作锁，避免连接使用紊乱
     */
    private static final Object APICLIENT_LOCK = new Object();

    /**
     * api client 连接超时
     */
    private static final int APICLIENT_CONNECT_TIMEOUT = 30000;

    /**
     * 解决升级错误时activity onResume 稳定在3秒时间判断BridgeActivity上面有没有其他activity
     */
    private static final int UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT = 3000;

    /**
     * api client 解决错误拉起界面超时
     */
    private static final int APICLIENT_STARTACTIVITY_TIMEOUT = 3000;

    /**
     * client 连接超时消息
     */
    private static final int APICLIENT_TIMEOUT_HANDLE_MSG = 3;

    /**
     * client 拉起activity超时消息
     */
    private static final int APICLIENT_STARTACTIVITY_TIMEOUT_HANDLE_MSG = 4;

    /**
     * 解决升级错误时activity onResume 稳定在3秒时间判断BridgeActivity上面有没有其他activity
     */
    private static final int UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT_HANDLE_MSG = 5;

    /**
     * 最大尝试连接次数
     */
    private static final int MAX_RESOLVE_TIMES = 3;

    /**
     * 上下文，用来处理连接失败
     */
    private Context context;

    /**
     * 当前应用包名
     */
    private String curAppPackageName;

    /**
     * HuaweiApiClient 实例
     */
    private HuaweiApiClient apiClient;

    /**
     * 是否允许解决connect错误（解决connect错误需要拉起activity）
     */
    private boolean allowResolveConnectError = false;

    /**
     * 是否正在解决连接错误
     */
    private boolean isResolving;

    /**
     * HMSSDK 解决错误的activity
     */
    private BridgeActivity resolveActivity;

    /**
     * 是否存在其他activity覆盖在升级activity之上
     */
    private boolean hasOverActivity = false;

    /**
     * 当前剩余尝试次数
     */
    private int curLeftResolveTimes = MAX_RESOLVE_TIMES;

    /**
     * 连接回调
     */
    private List<IClientConnectCallback> connCallbacks = new ArrayList<IClientConnectCallback>();

    /**
     * 注册的静态回调
     */
    private List<IClientConnectCallback> staticCallbacks = new ArrayList<IClientConnectCallback>();

    private static class EmptyConnectCallback implements IClientConnectCallback {

        private String msgPre;

        private EmptyConnectCallback(String msgPre){
            this.msgPre = msgPre;
        }

        /**
         * HuaweiApiClient 连接结果回调
         *
         * @param rst    结果码
         * @param client HuaweiApiClient 实例
         */
        @Override
        public void onConnect(int rst, HuaweiApiClient client) {
            HMSAgentLog.d(msgPre + rst);
        }
    }

    /**
     * 超时handler用来处理client connect 超时
     */
    private Handler timeoutHandler = new Handler(new Handler.Callback() {
        @Override
        public boolean handleMessage(Message msg) {

            boolean hasConnCallbacks;
            synchronized (CALLBACK_LOCK) {
                hasConnCallbacks = !connCallbacks.isEmpty();
            }

            if (msg != null && msg.what == APICLIENT_TIMEOUT_HANDLE_MSG && hasConnCallbacks) {
                HMSAgentLog.d("connect time out");
                resetApiClient();
                onConnectEnd(HMSAgent.AgentResultCode.APICLIENT_TIMEOUT);
                return true;
            } else if (msg != null && msg.what == APICLIENT_STARTACTIVITY_TIMEOUT_HANDLE_MSG && hasConnCallbacks) {
                HMSAgentLog.d("start activity time out");
                onConnectEnd(HMSAgent.AgentResultCode.APICLIENT_TIMEOUT);
                return true;
            } else if (msg != null && msg.what == UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT_HANDLE_MSG && hasConnCallbacks) {
                HMSAgentLog.d("Discarded update dispose:hasOverActivity=" + " resolveActivity=" + resolveActivity);
                if (hasOverActivity && resolveActivity != null && !resolveActivity.isFinishing()) {
                    onResolveErrorRst(ConnectionResult.CANCELED);
                }
                return true;
            }
            return false;
        }
    });

    /**
     * 私有构造方法
     */
    private ApiClientMgr () {
    }

    /**
     * 初始化
     * @param app 应用程序
     */
    public void init(Application app) {

        HMSAgentLog.d("init");

        // 保存应用程序context
        context = app.getApplicationContext();

        // 取得应用程序包名
        curAppPackageName = app.getPackageName();

        // 注册activity onResume回调
        ActivityMgr.INST.unRegisterActivitResumeEvent(this);
        ActivityMgr.INST.registerActivitResumeEvent(this);
    }

    /**
     * 断开apiclient，一般不需要调用
     */
    public void release() {
        HMSAgentLog.d("release");
        HuaweiApiClient client =  getApiClient();
        if (client != null) {
            client.disconnect();
        }

        synchronized (STATIC_CALLBACK_LOCK) {
            staticCallbacks.clear();
        }

        synchronized (CALLBACK_LOCK) {
            connCallbacks.clear();
        }
    }

    /**
     * 获取当前的 HuaweiApiClient
     * @return HuaweiApiClient 实例
     */
    public HuaweiApiClient getApiClient() {
        synchronized (APICLIENT_LOCK) {
            return apiClient;
        }
    }

    /**
     * 判断client是否已经连接
     * @param client 要检测的client
     * @return 是否已经连接
     */
    public boolean isConnect(HuaweiApiClient client) {
        return client != null && client.isConnected();
    }

    /**
     * 注册apiclient连接事件
     * @param staticCallback 连接回调
     */
    public void registerClientConnect(IClientConnectCallback staticCallback){
        synchronized (STATIC_CALLBACK_LOCK) {
            staticCallbacks.add(staticCallback);
        }
    }

    /**
     * 反注册apiclient连接事件
     * @param staticCallback 连接回调
     */
    public void removeClientConnectCallback(IClientConnectCallback staticCallback) {
        synchronized (STATIC_CALLBACK_LOCK) {
            staticCallbacks.remove(staticCallback);
        }
    }

    /**
     * 重新创建apiclient
     * 2种情况需要重新创建：1、首次 2、client的状态已经紊乱
     * @return 新创建的client
     */
    private HuaweiApiClient resetApiClient(){
        synchronized (APICLIENT_LOCK) {
            if (apiClient != null) {
                // 对于老的apiClient，1分钟后才丢弃，防止外面正在使用过程中这边disConnect了
                disConnectClientDelay(apiClient, 60000);
            }

            HMSAgentLog.d("reset client");

            // 这种重置client，极端情况可能会出现2个client都回调结果的情况。此时可能出现rstCode=0，但是client无效。
            // 因为业务调用封装中都进行了一次重试。所以不会有问题
            apiClient = new HuaweiApiClient.Builder(context)
                    .addApi(HuaweiPush.PUSH_API)
                    .addConnectionCallbacks(INST)
                    .addOnConnectionFailedListener(INST)
                    .build();
            return apiClient;
        }
    }
    /**
     * 连接
     * @param callback 连接回调,一定不能为null
     */
    public void connect(IClientConnectCallback callback, boolean allowResolve) {

        if (context == null) {
            callback.onConnect(HMSAgent.AgentResultCode.HMSAGENT_NO_INIT, null);
            return;
        }

        HuaweiApiClient client =  getApiClient();
        // client 有效，则直接回调
        if (client != null && client.isConnected()) {
            HMSAgentLog.d("client is valid");
            callback.onConnect(0, client);
            return;
        } else {
            // client无效，将callback加入队列，并启动连接
            synchronized (CALLBACK_LOCK) {
                HMSAgentLog.d("client is invalid：size=" + connCallbacks.size());
                allowResolveConnectError = allowResolveConnectError || allowResolve;
                if (connCallbacks.isEmpty()) {
                    connCallbacks.add(callback);

                    // 连接尝试最大次数
                    curLeftResolveTimes = MAX_RESOLVE_TIMES;

                    startConnect();
                } else {
                    connCallbacks.add(callback);
                }
            }
        }
    }

    /**
     * 线程中进行Huawei Api Client 的连接
     */
    private void startConnect() {

        // 触发一次连接将重试次数减1
        curLeftResolveTimes--;

        HMSAgentLog.d("start thread to connect");
        new Thread() {
            @Override
            public void run() {
                super.run();
                HuaweiApiClient client =  getApiClient();
                if (client == null) {
                    HMSAgentLog.d("create client");
                    client = resetApiClient();
                }

                HMSAgentLog.d("connect");
                timeoutHandler.sendEmptyMessageDelayed(APICLIENT_TIMEOUT_HANDLE_MSG, APICLIENT_CONNECT_TIMEOUT);
                client.connect();
            }
        }.start();
    }

    /**
     * Huawei Api Client 连接结束方法
     * @param rstCode client 连接结果码
     */
    private void onConnectEnd(final int rstCode) {
        HMSAgentLog.d("connect end:" + rstCode);

        synchronized (CALLBACK_LOCK) {
            // 回调各个回调接口连接结束
            for (IClientConnectCallback callback : connCallbacks) {
                aSysnCallback(rstCode, callback);
            }
            connCallbacks.clear();

            // 恢复默认不显示
            allowResolveConnectError = false;
        }

        synchronized (STATIC_CALLBACK_LOCK) {
            // 回调各个回调接口连接结束
            for (IClientConnectCallback callback : staticCallbacks) {
                aSysnCallback(rstCode, callback);
            }
            staticCallbacks.clear();
        }
    }

    /**
     * 起线程回调各个接口，避免其中一个回调者耗时长影响其他调用者
     * @param rstCode 结果码
     * @param callback 回调
     */
    private void aSysnCallback(final int rstCode, final IClientConnectCallback callback) {
        new Thread() {
            @Override
            public void run() {
                super.run();
                HuaweiApiClient client =  getApiClient();
                HMSAgentLog.d("callback connect: rst=" + rstCode + " apiClient=" + client);
                callback.onConnect(rstCode, client);
            }
        }.start();
    }

    /**
     * Activity onResume回调
     *
     * @param activity 发生 onResume 事件的activity
     */
    @Override
    public void onActivityResume(Activity activity) {

        // 如果正在解决错误，则处理被覆盖的场景
        HMSAgentLog.d("is resolving:" + isResolving);
        if (isResolving && !PACKAGE_NAME_HIAPP.equals(curAppPackageName)) {
            if (activity instanceof BridgeActivity) {
                resolveActivity = (BridgeActivity)activity;
                hasOverActivity = false;
                HMSAgentLog.d("received bridgeActivity:" + resolveActivity);
            } else if (resolveActivity != null && !resolveActivity.isFinishing()){
                hasOverActivity = true;
                HMSAgentLog.d("received other Activity:" + resolveActivity);
            }
            timeoutHandler.removeMessages(UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT_HANDLE_MSG);
            timeoutHandler.sendEmptyMessageDelayed(UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT_HANDLE_MSG, UPDATE_OVER_ACTIVITY_CHECK_TIMEOUT);
        }
    }

    /**
     * connect fail 解决结果回调， 由 HMSAgentActivity 在 onActivityResult 中调用
     * @param result 解决结果
     */
    void onResolveErrorRst(int result) {
        HMSAgentLog.d("result="+result);
        isResolving = false;
        resolveActivity = null;
        hasOverActivity = false;

        if(result == ConnectionResult.SUCCESS) {
            HuaweiApiClient client =  getApiClient();
            if (!client.isConnecting() && !client.isConnected() && curLeftResolveTimes > 0) {
                startConnect();
                return;
            }
        }

        onConnectEnd(result);
    }

    /**
     * HMSAgentActivity 拉起拉了（走了onCreate）
     */
    void onActivityLunched(){
        HMSAgentLog.d("resolve onActivityLunched");
        // 拉起界面回调，移除拉起界面超时
        timeoutHandler.removeMessages(APICLIENT_STARTACTIVITY_TIMEOUT_HANDLE_MSG);
        isResolving = true;
    }

    /**
     * Huawe Api Client 连接成功回到
     */
    @Override
    public void onConnected() {
        HMSAgentLog.d("connect success");
        timeoutHandler.removeMessages(APICLIENT_TIMEOUT_HANDLE_MSG);
        onConnectEnd(ConnectionResult.SUCCESS);
    }

    /**
     * 当client变成断开状态时会被调用。这有可能发生在远程服务出现问题时（例如：出现crash或资源问题导致服务被系统杀掉）。
     * 当被调用时，所有的请求都会被取消，任何listeners都不会被执行。需要 CP 开发代码尝试恢复连接（connect）。
     * 应用程序应该禁用需要服务的相关UI组件，等待{@link #onConnected()} 回调后重新启用他们。<br>
     *
     * @param cause 断开的原因. 常量定义： CAUSE_*.
     */
    @Override
    public void onConnectionSuspended(int cause) {
        HMSAgentLog.d("connect suspended");
        connect(new EmptyConnectCallback("onConnectionSuspended try end:"), true);
    }

    /**
     * 建立client到service的连接失败时调用
     *
     * @param result 连接结果，用于解决错误和知道什么类型的错误
     */
    @Override
    public void onConnectionFailed(ConnectionResult result) {
        timeoutHandler.removeMessages(APICLIENT_TIMEOUT_HANDLE_MSG);

        if (result == null) {
            HMSAgentLog.e("result is null");
            onConnectEnd(HMSAgent.AgentResultCode.RESULT_IS_NULL);
            return;
        }

        int errCode = result.getErrorCode();
        HMSAgentLog.d("errCode=" + errCode + " allowResolve=" + allowResolveConnectError);

        if(HuaweiApiAvailability.getInstance().isUserResolvableError(errCode) && allowResolveConnectError) {
            Activity activity = ActivityMgr.INST.getLastActivity();
            if (activity != null) {
                try {
                    timeoutHandler.sendEmptyMessageDelayed(APICLIENT_STARTACTIVITY_TIMEOUT_HANDLE_MSG, APICLIENT_STARTACTIVITY_TIMEOUT);
                    Intent intent = new Intent(activity, HMSAgentActivity.class);
                    intent.putExtra(HMSAgentActivity.CONN_ERR_CODE_TAG, errCode);
                    activity.startActivity(intent);
                    return;
                } catch (Exception e) {
                    HMSAgentLog.e("start HMSAgentActivity exception:" + e.getMessage());
                    onConnectEnd(HMSAgent.AgentResultCode.START_ACTIVITY_ERROR);
                    return;
                }
            } else {
                // 当前没有界面处理不了错误
                HMSAgentLog.d("no activity");
                onConnectEnd(HMSAgent.AgentResultCode.NO_ACTIVITY_FOR_USE);
                return;
            }
        } else {
            //其他错误码直接透传
        }

        onConnectEnd(errCode);
    }

    private static void disConnectClientDelay(final HuaweiApiClient clientTmp, int delay) {
        new Handler().postDelayed(new Runnable() {
            @Override
            public void run() {
                clientTmp.disconnect();
            }
        }, delay);
    }
}

#!/usr/bin/env python
"""Time-variable calibration for ATCA
Usage:
  timevariation_cal.py <dataset> [--calibrator=<cal>] [--segment=<min>] [--slop=<min>]
-h --help             show this
-c --calibrator CAL   the name of the calibrator [default: 1934-638]
-s --segment LEN      the length of each calibration segment, in minutes [default: 2]
-S --slop SLOP        a tolerance on the segment length, if it makes sense to extend it, in minutes [default: 1]
"""
from docopt import docopt
from mirpy import miriad
import ephem
from datetime import date, datetime, timedelta
import fnmatch
import os
import shutil
import numpy as np
import sys
import json
import math
import re
# A routine to turn a Miriad type time string into a ephem Date.
def mirtime_to_date(mt):
    year = 2000 + int(mt[0:2])
    monthShort = mt[2:5]
    date = int(mt[5:7])
    hour = int(mt[8:10])
    minute = int(mt[11:13])
    second = int(round(float(mt[14:18])))
    monthDict = { 'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
                  'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12 }
    dateString = "%4d/%02d/%02d %02d:%02d:%02d" % (year, monthDict[monthShort], date,
                                                   hour, minute, second)
    return ephem.Date(dateString)
def datetime_to_mirtime(dt):
    # Output a Miriad formatted date.
    rs = dt.strftime("%y%b%d:%H:%M:%S").lower()
    return rs
# Use a uvlist log to get the cycle time.
def filter_uvlist_variables(logfile_name):
    # We send back a dictionary.
    rd = { 'cycle_time': -1. }
    with open(logfile_name, "r") as fp:
        loglines = fp.readlines()
    for i in xrange(0, len(loglines)):
        index_elements = loglines[i].split()
        if ((len(index_elements) > 2) and
            (index_elements[0] == "inttime") and (index_elements[1] == ":")):
            rd['cycle_time'] = float(index_elements[2])
    return rd
def filter_uvlist_antennas(output):
    # We send back a dictionary.
    rd = { 'telescope': "", 'latitude': "", 'longitude': "", 'antennas': [] }
    outlines = output.split('\n')
    coords = 0
    for i in xrange(0, len(outlines)):
        index_elements = outlines[i].split()
        if (len(index_elements) > 0):
            if (index_elements[0] == "Telescope:"):
                rd['telescope'] = index_elements[1]
            elif (index_elements[0] == "Latitude:"):
                rd['latitude'] = index_elements[1]
            elif (index_elements[0] == "Longitude:"):
                rd['longitude'] = index_elements[1]
            elif ((len(index_elements) == 3) and (index_elements[1] == "----------")):
                coords = 1
            elif (coords == 1):
                ant = { 'number': int(index_elements[0]),
                        'coord_x': float(index_elements[1]),
                        'coord_y': float(index_elements[2]),
                        'coord_z': float(index_elements[3]) }
                rd['antennas'].append(ant)
    return rd
# Use uvindex to work out the necessary parameters of this dataset.
def filter_uvindex(output):
    # We send back a dictionary.
    rd = { 'index': { 'time': [], 'source': [], 'calcode': [], 'antennas': [],
                      'spectral_channels': [], 'wideband_channels': [], 'freq_config': [],
                      'record_number': [] },
           'total_time': 0,
           'freq_configs': [], 'polarisations': [], 'sources': [] }
    outlines = output.split('\n')
    section = 0
    freqconfig_n = 0
    freqconfig_found = 0
    fc = None
    sourcearea = 0
    for i in xrange(0, len(outlines)):
        index_elements = outlines[i].split()
        if ((section == 0) and (len(outlines[i]) >= 74)):
            indexTime = mirtime_to_date(outlines[i][0:18])
            if ((index_elements[1] != "Total") and (index_elements[2] != "number")):
                # This is a regular line.
                offset = 0
                rd['index']['time'].append(indexTime)
                rd['index']['source'].append(index_elements[1])
                # Check if we have a calibrator code.
                calcode = outlines[i][36:37]
                if (calcode == " "):
                    # No calibrator code.
                    offset = 1
                rd['index']['calcode'].append(calcode)
                rd['index']['antennas'].append(int(index_elements[3 - offset]))
                rd['index']['spectral_channels'].append(int(index_elements[4 - offset]))
                rd['index']['wideband_channels'].append(int(index_elements[5 - offset]))
                rd['index']['freq_config'].append(int(index_elements[6 - offset]))
                rd['index']['record_number'].append(int(index_elements[7 - offset]))
            else:
                # We've moved to the next section
                section = 1
        elif ((section == 1) and (len(index_elements) > 0) and (index_elements[0] == "Total") and
              (index_elements[1] == "observing")):
            # We've found the total amount of observing time.
            rd['total_time'] = float(index_elements[4])
            section = 2
        elif (section == 2):
            if ((len(index_elements) > 0) and (index_elements[0] == "Frequency")
                and (index_elements[1] == "Configuration")):
                freqconfig_n = int(index_elements[2])
                freqconfig_found = 1
                if (fc is not None):
                    rd['freq_configs'].append(fc)
                fc = { 'number': freqconfig_n, 'nchannels': [],
                       'frequency1': [], 'frequency_increment': [],
                       'rest_frequency': [], 'ifchain': [] }
            elif (freqconfig_found == 1):
                freqconfig_found = 2
            elif (freqconfig_found == 2):
                if (outlines[i] == ""):
                    freqconfig_found = 0
                else:
                    # This is the actual line.
                    fc['nchannels'].append(int(index_elements[0]))
                    fc['frequency1'].append(float(index_elements[1]))
                    fc['frequency_increment'].append(float(index_elements[2]))
                    fc['rest_frequency'].append(float(index_elements[3]))
                    fc['ifchain'].append(int(index_elements[5]))
            elif (outlines[i] == "------------------------------------------------"):
                if (fc is not None):
                    rd['freq_configs'].append(fc)
                section = 3
        elif (section == 3):
            if ((len(index_elements) > 0) and (index_elements[0] == "There") and
                (index_elements[3] == "records") and (index_elements[5] == "polarization")):
                rd['polarisations'].append(index_elements[6])
            elif (outlines[i] == "------------------------------------------------"):
                section = 4
        elif (section == 4):
            if ((len(index_elements) > 0) and (index_elements[0] == "Source")):
                sourcearea = 1
            elif ((len(index_elements) > 2) and (sourcearea == 1)):
                src = { 'name': index_elements[0], 'calcode': index_elements[1],
                        'right_ascension': index_elements[2], 'declination': index_elements[3],
                        'dra': index_elements[4], 'ddec': index_elements[5] }
                rd['sources'].append(src)
    # Convert things into numpy arrays for easy where-ing later.
    rd['index']['time'] = np.array(rd['index']['time'])
    rd['index']['source'] = np.array(rd['index']['source'])
    rd['index']['calcode'] = np.array(rd['index']['calcode'])
    rd['index']['antennas'] = np.array(rd['index']['antennas'])
    rd['index']['spectral_channels'] = np.array(rd['index']['spectral_channels'])
    rd['index']['wideband_channels'] = np.array(rd['index']['wideband_channels'])
    rd['index']['freq_config'] = np.array(rd['index']['freq_config'])
    rd['index']['record_number'] = np.array(rd['index']['record_number'])

    return rd
def split_into_segments(idx):
    # We go through a uvindex dictionary and return segments.
    # Each segment is a single source, at a single frequency,
    # with a start and end time.
    segs = []
    oldsrc = ""
    oldconfig = -1
    sseg = None
    for i in xrange(0, len(idx['index']['source'])):
        if ((idx['index']['source'][i] != oldsrc) or
            (idx['index']['freq_config'][i] != oldconfig)):
            if ((oldsrc != "") and (oldconfig != -1)):
                # Put the segment on the list.
                segs.append(sseg)
            oldsrc = idx['index']['source'][i]
            oldconfig = idx['index']['freq_config'][i]
            sseg = { 'source': idx['index']['source'][i],
                     'freq_config': idx['index']['freq_config'][i],
                     'start_time': ephem.Date(idx['index']['time'][i]),
                     'end_time': ephem.Date(idx['index']['time'][i]) }
        else:
            sseg['end_time'] = ephem.Date(idx['index']['time'][i])
    # Have to push the last segment on.
    segs.append(sseg)
    return segs
def dataset_find(srcname, freq=None):
    srcpat = "%s.*" % srcname
    if (freq is not None):
        srcpat = "%s.%d" % (srcname, freq)
    matches = []
    for root, dirnames, filenames in os.walk('.'):
        for filename in fnmatch.filter(dirnames, srcpat):
            # Check if this has data.
            fname = os.path.join(root, filename)
            cname = "%s/visdata" % fname
            if ((os.path.isdir(fname)) and (os.path.isfile(cname))):
                matches.append(fname)
    return matches
def filter_uvplt(output):
    outlines = output.split('\n')
    rd = { 'nvisibilities': 0 }
    for i in xrange(0, len(outlines)):
        index_elements = outlines[i].split()
        if (len(index_elements) < 3):
            continue
        if ((index_elements[0] == "Read") and
            (index_elements[2] == "visibilities")):
            rd['nvisibilities'] = int(index_elements[1])
    return rd
def filter_closure(output):
    outlines = output.split('\n')
    rd = { 'theoretical_rms': 0, 'measured_rms': 0 }
    for i in xrange(0, len(outlines)):
        index_elements = outlines[i].split()
        if (len(index_elements) < 1):
            continue
        if (index_elements[0] == "Actual"):
            rd['measured_rms'] = float(index_elements[-1])
        elif (index_elements[0] == "Theoretical"):
            rd['theoretical_rms'] = float(index_elements[-1])
    return rd
def filter_uvfstats(output):
    outlines = output.split('\n')
    rd = { 'flagged_fraction': 0 }
    strt = 0
    nchans = 0
    nflagged = 0
    for i in xrange(0, len(outlines)):
        index_elements = outlines[i].split()
        if (len(index_elements) < 1):
            continue
        if (strt == 1):
            nchans = nchans + 1
            if (index_elements[1] < 15):
                nflagged = nflagged + 1
        else:
            if (index_elements[0] == "-------"):
                strt = 1
    rd['flagged_fraction'] = "%.2f" % (nflagged / nchans)
    return rd
def calibrate(srcname, calname, fconfig, stime, etime):
    smtime = datetime_to_mirtime(stime)
    emtime = datetime_to_mirtime(etime)
    selstring = "time(%s,%s)" % (smtime, emtime)
    print "  calibrating source %s with selection %s" % (srcname, selstring)
    # Find all the relevant datasets.
    dsets = dataset_find(srcname)

    cfreqs = []
    rv = { 'code': 0, 'frequencies': [] }
    for i in xrange(0, len(dsets)):
        fname = dsets[i]
        # Check if this is one of the frequencies in this configuration.
        setf = int(fname.split(".")[-1])
        for j in xrange(0, len(fconfig['nchannels'])):
            c = (fconfig['frequency1'][j] + (fconfig['nchannels'][j] - 1) *
                 fconfig['frequency_increment'][j] / 2.) * 1000.
            fdiff = abs(c - setf)
            if (fdiff <= abs(fconfig['frequency_increment'][j] * 1000.)):
                cfreqs.append([ setf, j, fname ])
                rv['frequencies'].append(setf)
    # Calibrate per frequency.
    for i in xrange(0, len(cfreqs)):
        dset = cfreqs[i][2]
        csets = dataset_find(calname, cfreqs[i][0])
        cset = csets[0]
        # Check that we actually have data in this time range.
        miriad.set_filter('uvplt', filter_uvplt)

        uvout = miriad.uvplt(vis=dset, axis="time,amp", device="/null",
                             options="nopol,nocal,nopass", stokes="xx,yy",
                             select=selstring)
        if (uvout['nvisibilities'] > 0):
            # Do the calibration.
            print "  calibrating frequency %d MHz" % cfreqs[i][0]
            miriad.gpcopy(vis=cset, out=dset)
            miriad.gpcal(vis=dset, interval="0.1", options="xyvary,nopol,qusolve",
                         nfbin="2", refant="3", select=selstring)
            miriad.gpboot(vis=dset, cal=cset, select=selstring)
            rv['code'] = 1
        else:
            print "  Unable to find any data for this time range!" % selstring
            rv['code'] = 0
    return rv
def measure_closure_phase(srcname, freq, stime, etime):
    print "    closure phase %.1f MHz" % freq
    closurelog = "closure_log.txt"
    selstring = "time(%s,%s)" % (datetime_to_mirtime(stime),
                                 datetime_to_mirtime(etime))
    if (os.path.isfile(closurelog)):
        os.remove(closurelog)
    # Find the data set.
    dsets = dataset_find(srcname, freq)
    miriad.set_filter('closure', filter_closure)
    cout = miriad.closure(vis=dsets[0], stokes="i", device="/null",
                          options="log", select=selstring)
    rv = { 'closure_phase': { 'theoretical_rms': cout['theoretical_rms'],
                              'measured_rms': cout['measured_rms'],
                              'average_value': -999 } }
    if (os.path.isfile(closurelog)):
        with open(closurelog, "r") as fp:
            loglines = fp.readlines()
        pvals = []
        for i in xrange(0, len(loglines)):
            lels = loglines[i].split()
            if (len(lels) < 1):
                continue
            if (lels[0] == "Antennas"):
                continue
            pvals.append(float(lels[-1]))
        rv['closure_phase']['average_value'] = np.average(pvals)
    return rv
def measure_flagging_statistic(srcname, freq, stime, etime):
    print "    flagging %.1f MHz" % freq
    miriad.set_filter('uvfstats', filter_uvfstats)
    selstring = "time(%s,%s)" % (datetime_to_mirtime(stime),
                                 datetime_to_mirtime(etime))
    # Find the data set.
    dsets = dataset_find(srcname, freq)
    uo = miriad.uvfstats(vis=dsets[0], mode="channel",
                         options="absolute,unflagged",
                         select=selstring)
    return uo['flagged_fraction']
def calculate_hourangle(obs, obstime, src):
    obs.date = obstime
    src.compute(obs)
    lst = obs.sidereal_time() * 180. / (15. * math.pi)
    ra = src.ra * 180. / (15. * math.pi)
    ha = lst - ra
    if (ha < -12):
        ha = ha + 24
    elif (ha > 12):
        ha = ha - 24
    return ha
